-- The PENTA IQ GRIP code key (Code keys -> Parting -> PENTA IQ GRIP), from the
-- ISCAR e-catalog's PENTA IQ GRIP families (PENTA D22 / D32 / D40 inserts,
-- PCHR/L-D##-#-IQ / -JHP tools); kept if one exists. The PENTACUT key leaves
-- its PENTA D tool section to it, and its subtitle changes only if unedited.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.pentaiq', $ck${"title": "PENTA IQ GRIP code key – inserts and tools", "subtitle": "PENTA D inserts with 5 cutting edges for parting and grooving up to Ø22 / 32 / 40 mm, and their PCHR/L-D tools", "example": "PENTA D32N200C020", "decoder": "penta-iq", "sections": [{"key": "i-family", "title": "Insert – family", "sample": "PENTA", "rows": [{"code": "PENTA", "meaning": "Pentagonal insert with 5 cutting edges"}]}, {"key": "i-size", "title": "Insert – size", "sample": "D32", "rows": [{"code": "D22", "meaning": "PENTA D 22 – parting up to Ø22 mm (PCHR/L-D22 tools)"}, {"code": "D32", "meaning": "PENTA D 32 – parting up to Ø32 mm (PCHR/L-D32 tools)"}, {"code": "D40", "meaning": "PENTA D 40 – parting up to Ø40 mm (PCHR/L-D40 tools)"}]}, {"key": "i-hand", "title": "Insert – hand", "sample": "N", "rows": [{"code": "N", "meaning": "Neutral"}, {"code": "R", "meaning": "Right-hand (lead angle)"}, {"code": "L", "meaning": "Left-hand (lead angle)"}]}, {"key": "i-width", "title": "Insert – cutting width", "sample": "200", "rows": [{"code": "###", "meaning": "Cutting width x100 (200 = 2.00 mm, 300 = 3.00 mm)"}]}, {"key": "i-chip", "title": "Chipformer", "sample": "C", "rows": [{"code": "C", "meaning": "Parting and grooving hard materials, tough and general applications"}, {"code": "J", "meaning": "Soft materials, parting tubes, small and thin-walled parts"}, {"code": "PB", "meaning": "Bearing steel and other ductile materials"}]}, {"key": "i-radius", "title": "Insert – corner radius", "sample": "020", "rows": [{"code": "###", "meaning": "Corner radius x100 (e.g. 020 = 0.20 mm)"}]}, {"key": "i-lead", "title": "Insert – lead angle", "rows": [{"code": "#D", "meaning": "Lead angle in degrees (e.g. -6D = 6°)"}, {"code": "##D", "meaning": "Lead angle in degrees (e.g. -15D = 15°)"}]}, {"key": "t-family", "title": "Tool – family", "rows": [{"code": "PCH", "meaning": "Grooving and parting tools carrying PENTA D inserts (PCHR / PCHL)"}]}, {"key": "t-hand", "title": "Tool – hand", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}]}, {"key": "t-height", "title": "Tool – shank", "rows": [{"code": "##", "meaning": "Shank size in mm (12, 16, 20, 25, 32)"}]}, {"key": "t-dia", "title": "Tool – PENTA D size", "rows": [{"code": "D##", "meaning": "For PENTA D## inserts; maximum cutting diameter in mm (D22, D32, D40)"}]}, {"key": "t-width", "title": "Tool – insert width", "rows": [{"code": "#", "meaning": "Insert width in mm (2: 2.00–2.40, 3)"}]}, {"key": "t-suffix", "title": "Tool – suffixes", "rows": [{"code": "IQ", "meaning": "IQ line"}, {"code": "JHP", "meaning": "Channels for high-pressure coolant"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;

UPDATE "AppSetting"
SET "value" = jsonb_set("value"::jsonb, '{sections}', (
  SELECT COALESCE(jsonb_agg(s), '[]'::jsonb) FROM jsonb_array_elements("value"::jsonb -> 'sections') s WHERE s ->> 'key' <> 't-dia'
))::text
WHERE "key" = 'codekey.penta';

UPDATE "AppSetting" SET "value" = jsonb_set("value"::jsonb, '{subtitle}', '"Inserts with 5 cutting edges: PENTA 17 / 24 / 34, PENTA 34F face grooving, PENTAS 27 blanks and PMN D (FLASHPENTA), and their tools"')::text
WHERE "key" = 'codekey.penta' AND "value"::jsonb ->> 'subtitle' = 'Inserts with 5 cutting edges: PENTA 17 / 24 / 34, PENTA 34F face grooving, PENTAS 27 blanks, PENTA D (PENTA IQ GRIP) and PMN D (FLASHPENTA), and their tools';
